const apiErrorKeys:Record<string,string>={'Username atau password salah.':'wrongLogin','Terlalu banyak percobaan. Coba lagi nanti.':'tooMany','Permintaan lintas situs ditolak.':'csrf','Kartu tidak ditemukan.':'invalidCard','Kode aktivasi salah.':'invalidActivation','Kartu sudah aktif.':'cardAlreadyActive','Tautan Google Review tidak valid.':'invalidReviewUrl'};
const Context=createContext<{language:Language;setLanguage:(language:Language)=>void;t:(key:string)=>string}>({language:'id',setLanguage:()=>{},t:key=>messages.id[key]??key});
export function LanguageProvider({children}:{children:ReactNode}){const [language,setCurrent]=useState<Language>('id');useEffect(()=>{const stored=localStorage.getItem('repiw-language');if(stored==='id'||stored==='en')setCurrent(stored)},[]);const setLanguage=(value:Language)=>{setCurrent(value);localStorage.setItem('repiw-language',value)};useEffect(()=>{document.documentElement.lang=language},[language]);const value=useMemo(()=>({language,setLanguage,t:(key:string)=>messages[language][key]??key}),[language]);return <Context.Provider value={value}>{children}</Context.Provider>}
export function useLanguage(){return useContext(Context)}
export function LanguageSwitcher(){const {language,setLanguage,t}=useLanguage();return <label className="language-switcher"><span className="sr-only">{t('language')}</span><select aria-label={t('language')} value={language} onChange={e=>setLanguage(e.target.value as Language)}><option value="id">{t('languageIndonesian')}</option><option value="en">{t('languageEnglish')}</option></select></label>}
export function localizedMessage(message:string,language:Language){const key=apiErrorKeys[message];return key?messages[language][key]:message}
